require("dotenv").config();
const PORT = process.env.PORT || 3001;
const express = require("express");
const cors = require("cors");
const tagsRoutes = require("./routes/tags");

const app = express();
app.use(cors());
app.use(express.json());

app.get("/", (req, res) => res.json({ status: "API is running" }));
app.use("/api/tags", tagsRoutes);
app.use((req, res) => res.status(404).json({ error: "Not found" }));

app.listen(PORT, () =>
  console.log(`Server running on http://localhost:${PORT}`),
);

import axios from "axios";

const TAGS_ENDPOINT = "/api/tags";

function normalizeTagsResponse(data) {
  if (Array.isArray(data?.tags)) {
    return data.tags;
  }

  return [];
}

async function fetchTags(signal) {
  const { data } = await axios.get(TAGS_ENDPOINT, { signal });

  return normalizeTagsResponse(data);
}

export { TAGS_ENDPOINT, fetchTags, normalizeTagsResponse };

